import { assetUrl } from '../../lib/asset';

type LogoVariant = 'onLight' | 'onDark';

interface LogoProps {
  variant: LogoVariant;
  className?: string;
  loading?: 'eager' | 'lazy';
  // Hides the image from assistive tech (empty alt and aria-hidden), for a second copy of the logo.
  decorative?: boolean;
}

// Intrinsic size of public/brand/vn-one-logo-*.webp, generated by
// scripts/build-brand-assets.mjs at a height of 96px. Logo.assets.test.ts
// checks these values against the files.
export const LOGO_WIDTH = 194;
export const LOGO_HEIGHT = 96;

const LOGO_SRC: Record<LogoVariant, string> = {
  onLight: assetUrl('/brand/vn-one-logo-dark.webp'),
  onDark: assetUrl('/brand/vn-one-logo-chrome.webp'),
};

export function Logo({ variant, className, loading = 'eager', decorative = false }: LogoProps) {
  return (
    <img
      src={LOGO_SRC[variant]}
      alt={decorative ? '' : 'VN One'}
      aria-hidden={decorative ? true : undefined}
      width={LOGO_WIDTH}
      height={LOGO_HEIGHT}
      loading={loading}
      decoding="async"
      className={className}
    />
  );
}
